  PERFORM pg_temp.f011_unique('clinical.content_material_bindings',ARRAY['release_id','material_kind']::text[]);
  PERFORM pg_temp.f011_fk('clinical.content_material_bindings',ARRAY['release_id','artifact_version']::text[],'clinical.content_releases',ARRAY['id','artifact_version']::text[],false);
