-- F011_CASE {"id":"CONTENT-COMPETING-DRAFTS","task":"T013","missing":{"kind":"table","name":"clinical.content_releases"},"purpose":"Initial/same-predecessor drafts share lineage-relative version under distinct release IDs","user":"owner","commit":false}
CREATE FUNCTION pg_temp.f011_case() RETURNS void LANGUAGE plpgsql AS $case$
BEGIN
  PERFORM pg_temp.f011_require_table('clinical.content_releases');
  PERFORM pg_temp.f011_check(NOT EXISTS(SELECT 1 FROM pg_constraint c WHERE c.conrelid='clinical.content_releases'::regclass AND c.contype='u' AND (SELECT array_agg(a.attname::text ORDER BY k.ordinality) FROM unnest(c.conkey) WITH ORDINALITY k(num,ordinality) JOIN pg_attribute a ON a.attrelid=c.conrelid AND a.attnum=k.num)=ARRAY['series_id','artifact_version']),'same-version competing drafts must be allowed');
  PERFORM pg_temp.f011_unique('clinical.content_releases',ARRAY['id','series_id','artifact_version']::text[]);
END $case$;
SELECT 'K04_CASE_COMPILED';
SELECT pg_temp.f011_case();

